import pyspark.sql.functions as F


def solve(spark):
    return (
        spark.table('item_page_events')
        .withColumn('stat_date', F.substring('event_ts', 1, 10))
        .groupBy('stat_date', 'item_id')
        .agg(
            F.countDistinct('user_id').alias('uniq_users'),
            F.lit(0).alias('anon_events'),
            F.count(F.lit(1)).alias('total_events'),
        )
    )
